imageType.gridLayerStyle:
{
  stringStyle: {
    fontSize: function(properties, zoom) {
        var size = (properties.type === 'ward') ? 10 : 12;
        size += 2*(zoom - 11);
        return size;
    },
    color: function(properties, zoom) {
        return (properties.type === 'ward') ? '#808080' : '#333333';
    },
    bgColor: '#ffffff',
    viewProp: 'nameJP'
  }
}

{
  strokeColor: '#e0e0e0',
  fillColor: function(properties, zoom, context) {
      return context.createPattern(document.getElementById('texture_ND'), 'repeat');
  },
  fillOpacity: 0.75
}

{
  strokeColor: '#e0e0e0',
  fillColor: function(properties, zoom, context) {
      return context.createPattern(document.getElementById('texture_ND'), 'repeat');
  },
  fillOpacity: 0.75
}

{
  strokeColor: '#e0e0e0',
  fillColor: function(properties, zoom, context) {
      return context.createPattern(document.getElementById('texture_ND'), 'repeat');
  },
  fillOpacity: 0.75
}

{
  stringStyle: {
    fontWeight: 'bold',
    fontSize: function(properties, zoom) {
        return Math.min(4 + (zoom - 3)*2, 24);
    },
    color: function(properties, zoom) {
        if(zoom < 8) return undefined;
        var rain10m = Number(properties.rain10m);
        if(isNaN(rain10m)) return undefined;
        if(rain10m >= 15)      return '#ff2800';
        else if(rain10m >= 10) return '#ffaa00';
        else if(rain10m >= 5)  return '#faf500';
        else if(rain10m >= 1)  return '#00aaff';
        else                   return '#f2f2ff';
    },
    bgColor: function(properties, zoom) {
        if(zoom < 8) return undefined;
        var rain10m = Number(properties.rain10m);
        if(isNaN(rain10m)) return undefined;
        if(rain10m >= 15)      return '#c0c0c0';
        else                   return '#404040';
    },
    viewProp: 'rain10m',
    convert: function(text) {
        return (text === '0.0') ? '0' : text;
    }
  },
  symbolStyle: {
    iconId: function(properties, zoom) {
        if(zoom >= 8) return undefined;
        var rain10m = Number(properties.rain10m);
        if(isNaN(rain10m) || rain10m <= 0) return undefined;
        if(rain10m >= 15)      return 'circle_255_040_000';
        else if(rain10m >= 10) return 'circle_255_170_000';
        else if(rain10m >= 5)  return 'circle_250_245_000';
        else if(rain10m >= 1)  return 'circle_000_170_255';
        else                   return 'circle_242_242_255';
    },
    size: function(properties, zoom) {
        var size = Math.min(10 + (zoom - 3)*2, 24) - 8;
        return [size, size];
    }
  }
}

{
  symbolStyle: {
    iconId: function(properties, zoom) {
        return 'icon_' + ((properties.type === 4) ? 'CG' : 'CC');
    },
    size: function(properties, zoom) {
        var size = Math.min(10 + (zoom - 3)*2, 24);
        return [size, size];
    }
  }
}

{
  bgStrokeColor: '#ffffff',
  strokeColor: '#ff0000',
  strokeWidth: 4
}

{
  bgStrokeColor: '#ffffff',
  strokeColor: '#ff0000',
  strokeWidth: 4
}

{
  bgStrokeColor: '#ffffff',
  strokeColor: '#ff0000',
  strokeWidth: 4
}

{
  bgStrokeColor: '#ffffff',
  strokeColor: '#ff0000',
  strokeWidth: 4,
  dashArray: function(properties, zoom) {
      return [2*(zoom - 2), zoom - 2];
  }
}

{
  stringStyle: {
    fontSize: function(properties, zoom) {
       var size = (properties.type === 'ward') ? 12 : 14;
       size += 2*(zoom - 12);
       return size;
    },
    fontWeight: 'bold',
    color: function(properties, zoom) {
        return (properties.type === 'ward') ? '#808080' : '#333333';
    },
    bgColor: '#ffffff',
    viewProp: 'nameEN'
  }
}

